 async function uploadBundle(raw:string,target:string){
  if(!user)throw Error("Sign in before importing materials");
  let found=extractJson(raw);
  if("error" in found)throw Error(found.error);
  let source:any=found.value;
  let lesson=(page==="lesson"||page==="lesson-test")?activeNode:null;
  let path=target==="new"||!subject?"/subjects/import":`/subjects/${encodeURIComponent(subject)}/import`+(target==="lesson"&&lesson?`?lesson_id=${encodeURIComponent(lesson.id)}`:"");
  let result=await api<any>(path,json("POST",source));
  let sid=String(result.subject_id),c=result.imported||{};
  setModal(null);
  setPromptForImport("");
  message(`Imported into ${result.title}: ${c.lessons||0} lessons, ${c.questions||0} questions, ${c.vocabulary||0} words, ${c.readings||0} readings, ${c.phrases||0} dictation phrases.`);
  let sameSubject=sid===subject;
  if(!sameSubject)skipSubjectEffect.current=sid;
  setSubject(sid);
  let [list]=await Promise.all([api<Subject[]>("/subjects"),load(sid,false,sameSubject)]);
  setSubjects(list);
 }
 async function deleteSubject(confirmation:string){
  await api(`/subjects/${encodeURIComponent(subject)}`,json("DELETE",{confirmation}));
  let list=await api<Subject[]>("/subjects");
  setSubjects(list);
  try{localStorage.removeItem("omnilearn.subject")}catch{}
  let next=list[0]?.id||"";
  if(!next){setNodes([]);setQuestions([]);setCards([]);setReadings([]);setDashboard(null);setMistakes([]);setStatuses({})}
  setSubject(next);
  setPage("dashboard");
  message("Subject deleted.");
 }
